python3 -c "
import json, numpy as np
d = json.load(open('/root/turn_residual_gating/results/d048_final_ar/ss_s123_ar_n50.json'))
r = d['results']
for bk, bv in sorted(r.items()):
    beta = bv['beta']
    curves = bv.get('gar_curves', [])
    if not curves: continue
    gars = []
    for c in curves:
        if len(c) > 2: gars.append(np.mean(c[2:]))
        elif len(c) == 1: gars.append(c[0])
    if gars:
        print(f'beta={beta}: mean={np.mean(gars):.4f} median={np.median(gars):.4f} std={np.std(gars):.4f} n={len(gars)}')
"
